import pyomo.environ as pyo

DATA = {
    "PRODUCTS": ["scooter", "bike"],
    "TEAMS": ["design", "engineering"],
    "profit": {"scooter": 200, "bike": 300},
    "hours_per_unit": {
        ("scooter", "design"): 2,
        ("scooter", "engineering"): 3,
        ("bike", "design"): 4,
        ("bike", "engineering"): 5,
    },
    "hours_available": {"design": 5000, "engineering": 6000},
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.PRODUCTS = pyo.Set(initialize=d["PRODUCTS"])
    model.TEAMS = pyo.Set(initialize=d["TEAMS"])

    model.production = pyo.Var(
        model.PRODUCTS,
        within=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.PRODUCTS)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.maximize)

    def team_capacity_rule(m, t):
        return sum(
            d["hours_per_unit"][(p, t)] * m.production[p] for p in m.PRODUCTS
        ) <= d["hours_available"][t]

    model.team_capacity = pyo.Constraint(
        model.TEAMS, rule=team_capacity_rule
    )

    return model


